import { test, expect } from '@playwright/test';

test.describe('Task Creation Form', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/tasks');
  });

  test('should successfully create a new task with valid form data', async ({ page }) => {
    // Verify the form is visible
    const form = page.getByRole('form', { name: /create task/i });
    await expect(form).toBeVisible();

    // Fill out the form fields using getByLabel
    const titleInput = page.getByLabel(/task title/i);
    await titleInput.fill('New Task');

    const descriptionInput = page.getByLabel(/task description/i);
    await descriptionInput.fill('This is a new task description');

    const dueDateInput = page.getByLabel(/due date/i);
    await dueDateInput.fill('2023-12-31');

    // Verify the save button is enabled
    const saveButton = page.getByRole('button', { name: /save/i });
    await expect(saveButton).toBeEnabled();

    // Click the save button
    await saveButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/task created successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify the task is listed in the tasks table
    const tasksTable = page.getByRole('table', { name: /tasks/i });
    await expect(tasksTable).toBeVisible();

    const taskRows = page.locator('[data-testid="task-row"]');
    await expect(taskRows).toHaveCount(1);

    // Verify the task details are displayed
    const taskName = page.getByText('New Task');
    await expect(taskName).toBeVisible();

    const taskDescription = page.getByText('This is a new task description');
    await expect(taskDescription).toBeVisible();

    const taskDueDate = page.getByText('2023-12-31');
    await expect(taskDueDate).toBeVisible();
  });

  test('should display error when creating a task with invalid data', async ({ page }) => {
    // Fill out the form fields using getByLabel
    const titleInput = page.getByLabel(/task title/i);
    await titleInput.fill('');

    const descriptionInput = page.getByLabel(/task description/i);
    await descriptionInput.fill('');

    const dueDateInput = page.getByLabel(/due date/i);
    await dueDateInput.fill('invalid date');

    // Verify the save button is disabled
    const saveButton = page.getByRole('button', { name: /save/i });
    await expect(saveButton).not.toBeEnabled();

    // Click the save button
    await saveButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/please fill all required fields/i);
    await expect(errorMessage).toBeVisible();

    // Verify the form is still visible
    const form = page.getByRole('form', { name: /create task/i });
    await expect(form).toBeVisible();

    // Verify the task is not listed in the tasks table
    const tasksTable = page.getByRole('table', { name: /tasks/i });
    await expect(tasksTable).toBeVisible();

    const taskRows = page.locator('[data-testid="task-row"]');
    await expect(taskRows).toHaveCount(0);
  });
});
